class AdminPanelProvider extends PanelProvider { public function panel(Panel $panel): Panel{$settings=app(GlobalSettings::class);View::share('globalSettings',$settings->all());return $panel->default()->id('admin')->path('admin')->login()->colors(['primary'=>$this->primaryColor($settings->get('appearance.primary_color','indigo'))])->discoverResources(in:app_path('Filament/Resources'),for:'App\\Filament\\Resources')->discoverPages(in:app_path('Filament/Pages'),for:'App\\Filament\\Pages')->pages([Pages\Dashboard::class])->discoverWidgets(in:app_path('Filament/Widgets'),for:'App\\Filament\\Widgets')->widgets([ModerationOverview::class,Widgets\AccountWidget::class])->middleware([EncryptCookies::class,AddQueuedCookiesToResponse::class,StartSession::class,AuthenticateSession::class,ShareErrorsFromSession::class,VerifyCsrfToken::class,SubstituteBindings::class,DisableBladeIconComponents::class,DispatchServingFilamentEvent::class])->authMiddleware([Authenticate::class]);}
 private function primaryColor(string $color): array {return match($color){'slate'=>Color::Slate,'gray'=>Color::Gray,'zinc'=>Color::Zinc,'red'=>Color::Red,'orange'=>Color::Orange,'amber'=>Color::Amber,'yellow'=>Color::Yellow,'lime'=>Color::Lime,'green'=>Color::Green,'emerald'=>Color::Emerald,'teal'=>Color::Teal,'cyan'=>Color::Cyan,'sky'=>Color::Sky,'blue'=>Color::Blue,'violet'=>Color::Violet,'purple'=>Color::Purple,'fuchsia'=>Color::Fuchsia,'pink'=>Color::Pink,default=>Color::Indigo};}
